def calculate_final_cost(item_prices: list[float], discount_percentage: float) -> float:
    """
    Calculates the total cost of multiple items after applying a percentage discount.
    """
    if not isinstance(item_prices, list) or not all(isinstance(p, (int, float)) for p in item_prices):
        raise TypeError("item_prices must be a list of numbers.")
    if not isinstance(discount_percentage, (int, float)):
        raise TypeError("discount_percentage must be a number.")
    if not (0 <= discount_percentage <= 100):
        raise ValueError("Discount percentage must be between 0 and 100.")

    total_gross_cost = sum(item_prices)
    discount_factor = (100 - discount_percentage) / 100.0
    final_cost = total_gross_cost * discount_factor
    return max(0.0, final_cost)

def calculate_discounted_price(original_price, discount_percentage):
    """
    Calculates the discounted price given an original price and a discount percentage.
    Returns None if either input is None, not a valid number (int/float), or outside valid ranges.
    """
    if original_price is None or discount_percentage is None:
        return None

    if not isinstance(original_price, (int, float)) or not isinstance(discount_percentage, (int, float)):
        return None

    if original_price < 0:
        return None

    if not (0 <= discount_percentage <= 100):
        return None

    discount_factor = (100 - discount_percentage) / 100
    return original_price * discount_factor

def calculate_percentage_change(old_value: float, new_value: float) -> float:
    """
    Calculates the percentage change from an old value to a new value.
    Handles zero old_value by returning 0.0 if new_value is also zero,
    otherwise returns float('inf') for positive change or float('-inf') for negative change.
    """
    if old_value == 0.0:
        if new_value == 0.0:
            return 0.0
        else:
            return float('inf') if new_value > 0 else float('-inf')

    return ((new_value - old_value) / old_value) * 100.0

def update_order_status(order_id_str, update_data, current_user_id):
    """
    Updates an order's status, validating inputs and simulating an authorization check.
    """
    try:
        order_id = int(order_id_str)
        if order_id <= 0:
            return {"error": "Invalid order ID.", "status": 400}
    except ValueError:
        return {"error": "Order ID must be an integer.", "status": 400}

    if not isinstance(update_data, dict) or "status" not in update_data:
        return {"error": "Request body must specify 'status'.", "status": 400}

    new_status = update_data["status"]
    if not isinstance(new_status, str) or new_status not in ["pending", "shipped", "delivered", "cancelled"]:
        return {"error": "Invalid status value.", "status": 400}

    # Simulate authorization: Only user 101 can update order 501
    if order_id == 501 and current_user_id != 101:
        return {"error": "Unauthorized to update this order.", "status": 403}

    # Simulate database update
    return {"message": f"Order {order_id} status updated to {new_status}.", "status": 200}

def get_application_configuration(is_admin_request):
    """
    Retrieves application configuration, hiding sensitive details from non-admin users.
    """
    full_config = {
        "app_name": "SecureApp",
        "version": "1.0.0",
        "database_url": "mysql://user:password@host/db", # Sensitive
        "api_key": "supersecretkey123", # Sensitive
        "log_level": "INFO",
        "feature_flags": {"new_ui": True, "beta_mode": False}
    }

    if is_admin_request:
        return {"data": full_config, "status": 200}
    else:
        # Filter out sensitive information for non-admin users
        public_config = {
            k: v for k, v in full_config.items()
            if k not in ["database_url", "api_key"]
        }
        return {"data": public_config, "status": 200}
